/*
 * benchmark_assembly.cpp
 * Summary:
 * - Benchmarks the genome assembler across multiple k values.
 * - Measures wall time and peak RAM per pipeline stage.
 * - Runs each configuration 3 times and reports mean ± stddev.
 * - Only tests the contig + scaffold pipeline (not Eulerian).
 * - Outputs a formatted table to stdout suitable for screenshots.
 *
 * Usage:
 *   ./BenchmarkAssembly
 *   ./BenchmarkAssembly path/to/reads.fastq
 *
 * Requirements:
 *   - psapi linked (-lpsapi) for Windows memory measurement
 *   - Input file should be generated by GenerateFastq for reproducible results
 */

#include <iostream>
#include <iomanip>
#include <fstream>
#include <string>
#include <vector>
#include <numeric>
#include <cmath>
#include <chrono>
#include <algorithm>

// Windows memory measurement
#include <windows.h>
#include <psapi.h>

#include "assembler/core/data_list.h"
#include "assembler/io/sequence_reader.h"
#include "assembler/construction/kmer_encoding.h"
#include "assembler/core/de_bruijn_graph.h"
#include "assembler/construction/contig_assembler.h"
#include "assembler/construction/scaffolder.h"

// ─────────────────────────────────────────────
// CONSTANTS
// ─────────────────────────────────────────────

static constexpr int    NUM_RUNS         = 3;
static constexpr char   DEFAULT_INPUT[]  = "../data/genomic/synthetic_3mb.fastq";
static const std::vector<size_t> K_VALUES = { 15, 20, 25, 30, 35, 51 };
// ─────────────────────────────────────────────
// TIMING HELPER
// ─────────────────────────────────────────────

using Clock     = std::chrono::high_resolution_clock;
using TimePoint = Clock::time_point;

static double ms(TimePoint a, TimePoint b) {
    return std::chrono::duration<double, std::milli>(b - a).count();
}

// ─────────────────────────────────────────────
// MEMORY HELPERS
// ─────────────────────────────────────────────

static size_t getWorkingSetMB() {
    PROCESS_MEMORY_COUNTERS pmi = {};
    GetProcessMemoryInfo(GetCurrentProcess(), &pmi, sizeof(pmi));
    return pmi.WorkingSetSize / (1024 * 1024);
}

static size_t getPeakWorkingSetMB() {
    PROCESS_MEMORY_COUNTERS pmi = {};
    GetProcessMemoryInfo(GetCurrentProcess(), &pmi, sizeof(pmi));
    return pmi.PeakWorkingSetSize / (1024 * 1024);
}


// ─────────────────────────────────────────────
// STATS HELPERS
// ─────────────────────────────────────────────

static double mean(const std::vector<double>& v) {
    return std::accumulate(v.begin(), v.end(), 0.0) / v.size();
}

static double stddev(const std::vector<double>& v) {
    if (v.size() < 2) return 0.0;
    double m   = mean(v);
    double sum = 0.0;
    for (double x : v) sum += (x - m) * (x - m);
    return std::sqrt(sum / v.size());
}

// ─────────────────────────────────────────────
// FILE PRE-SCAN
// Counts total bases in a FASTQ file so KmerTable
// can be sized accurately — avoids both over-
// allocation (inflates RAM numbers) and under-
// allocation (causes extra rehash cycles that
// inflate timing numbers).
// ─────────────────────────────────────────────

static size_t countTotalBases(const std::string& path) {
    std::ifstream f(path);
    if (!f.is_open())
        throw std::runtime_error("Cannot open: " + path);

    std::string line;
    size_t total   = 0;
    int    lineNum = 0;
    while (std::getline(f, line)) {
        if (lineNum % 4 == 1)   // sequence line in every 4-line FASTQ block
            total += line.length();
        ++lineNum;
    }
    return total;
}

static size_t countReads(const std::string& path) {
    std::ifstream f(path);
    std::string line;
    size_t lines = 0;
    while (std::getline(f, line)) ++lines;
    return lines / 4;
}

// ─────────────────────────────────────────────
// BENCHMARK RESULT STRUCTS
// ─────────────────────────────────────────────

struct StageResult {
    double parseMs    = 0.0;
    double encodeMs   = 0.0;
    double graphMs    = 0.0;
    double contigMs   = 0.0;
    double scaffoldMs = 0.0;
    double totalMs    = 0.0;
    size_t peakRamMB  = 0;
    size_t contigCount   = 0;
    size_t scaffoldCount = 0;
    size_t n50           = 0;
};

struct KResult {
    size_t k;
    // Per-run raw results
    std::vector<double> parseMs;
    std::vector<double> encodeMs;
    std::vector<double> graphMs;
    std::vector<double> contigMs;
    std::vector<double> scaffoldMs;
    std::vector<double> totalMs;
    std::vector<size_t> peakRamMB;
    // From last run (assembly quality metrics don't vary between runs)
    size_t contigCount   = 0;
    size_t scaffoldCount = 0;
    size_t n50           = 0;
};

// ─────────────────────────────────────────────
// N50 CALCULATION
// ─────────────────────────────────────────────

static size_t computeN50(const std::vector<ContigAssembler::Contig>& contigs) {
    if (contigs.empty()) return 0;

    std::vector<size_t> lengths;
    lengths.reserve(contigs.size());
    size_t total = 0;
    for (const auto& c : contigs) {
        lengths.push_back(c.sequence.length());
        total += c.sequence.length();
    }

    std::sort(lengths.rbegin(), lengths.rend());
    size_t accumulated = 0;
    size_t half        = (total + 1) / 2;
    for (size_t len : lengths) {
        accumulated += len;
        if (accumulated >= half) return len;
    }
    return 0;
}

// ─────────────────────────────────────────────
// SINGLE BENCHMARK RUN
// Runs the full contig + scaffold pipeline for
// one k value and returns per-stage timings.
// ─────────────────────────────────────────────

static StageResult runOnce(const std::string& path,
                            size_t k,
                            size_t totalBases) {
    StageResult result;

    std::cout << "\n    [parse]" << std::flush;
    auto t0 = Clock::now();
    std::ifstream file(path);
    if (!file.is_open())
        throw std::runtime_error("Cannot open: " + path);

    std::cout << " [encode]" << std::flush;
    auto t1 = Clock::now();
    result.parseMs = ms(t0, t1);

    KmerTable kTable(totalBases, k);
    SequenceReader::encodeAllReads(file, k, kTable);
    file.close();

    std::cout << " [graph]" << std::flush;
    auto t2 = Clock::now();
    result.encodeMs = ms(t1, t2);

    DeBruijnGraph graph(k, kTable.getNumItems() * 2);
    for (const auto& entry : kTable)
        for (size_t i = 0; i < entry.value; ++i)
            graph.addKmer(entry.key);

    std::cout << " [contigs]" << std::flush;
    auto t3 = Clock::now();
    result.graphMs = ms(t2, t3);

    ContigAssembler ct(graph);
    ct.computeContigs();
    auto contigs = ct.getContigs();

    std::cout << " [scaffold]" << std::flush;
    auto t4 = Clock::now();
    result.contigMs    = ms(t3, t4);
    result.contigCount = contigs.size();
    result.n50         = computeN50(contigs);

    Scaffolder scaffolder(contigs, graph,
                          ResolutionStrategy::scored(), &kTable);
    scaffolder.buildScaffolds();

    std::cout << " [done]" << std::flush;
    auto t5 = Clock::now();
    result.scaffoldMs    = ms(t4, t5);
    result.scaffoldCount = scaffolder.getScaffolds().size();

    result.totalMs  = ms(t0, t5);
    result.peakRamMB = getPeakWorkingSetMB();

    return result;
}

// ─────────────────────────────────────────────
// TABLE FORMATTING
// ─────────────────────────────────────────────

static void printSeparator(int width = 110) {
    std::cout << std::string(width, '-') << "\n";
}

static void printHeader() {
    printSeparator();
    std::cout
        << std::left
        << std::setw(4)  << "K"
        << std::setw(12) << "Parse(ms)"
        << std::setw(14) << "Encode(ms)"
        << std::setw(12) << "Graph(ms)"
        << std::setw(13) << "Contigs(ms)"
        << std::setw(14) << "Scaffold(ms)"
        << std::setw(12) << "Total(ms)"
        << std::setw(11) << "RAM(MB)"
        << std::setw(10) << "Contigs"
        << std::setw(10) << "Scaffolds"
        << std::setw(10) << "N50(bp)"
        << "\n";
    printSeparator();
}

static std::string fmtMeanStd(const std::vector<double>& v) {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(1)
        << mean(v) << " ±" << stddev(v);
    return oss.str();
}

static void printRow(const KResult& r) {
    std::cout
        << std::left
        << std::setw(4)  << r.k
        << std::setw(12) << fmtMeanStd(r.parseMs)
        << std::setw(14) << fmtMeanStd(r.encodeMs)
        << std::setw(12) << fmtMeanStd(r.graphMs)
        << std::setw(13) << fmtMeanStd(r.contigMs)
        << std::setw(14) << fmtMeanStd(r.scaffoldMs)
        << std::setw(12) << fmtMeanStd(r.totalMs)
        << std::setw(11) << mean(std::vector<double>(r.peakRamMB.begin(),
                                                      r.peakRamMB.end()))
        << std::setw(10) << r.contigCount
        << std::setw(10) << r.scaffoldCount
        << std::setw(10) << r.n50
        << "\n";
}

// ─────────────────────────────────────────────
// MAIN
// ─────────────────────────────────────────────

int main(int argc, char** argv) {
    const std::string inputPath = (argc >= 2) ? argv[1] : DEFAULT_INPUT;

    std::cout << "\n";
    std::cout << "╔══════════════════════════════════════════════════╗\n";
    std::cout << "║         Genome Assembler Benchmark               ║\n";
    std::cout << "╚══════════════════════════════════════════════════╝\n\n";

    std::cout << "Input file:  " << inputPath  << "\n";
    std::cout << "Runs per k:  " << NUM_RUNS   << "\n";
    std::cout << "K values:    ";
    for (size_t k : K_VALUES) std::cout << k << " ";
    std::cout << "\n";
    std::cout << "Pipeline:    Contig assembly + scored scaffolding\n\n";

    // Pre-scan file
    std::cout << "Pre-scanning input file... ";
    std::cout.flush();
    size_t totalBases = countTotalBases(inputPath);
    size_t totalReads = countReads(inputPath);
    std::cout << "done\n";
    std::cout << "Total reads:  " << totalReads << "\n";
    std::cout << "Total bases:  " << totalBases << "\n";
    std::cout << "Avg coverage: ~"
              << totalBases / (totalBases / totalReads)
              << "x\n\n";

    // Run benchmarks
    std::vector<KResult> results;

    for (size_t k : K_VALUES) {
        // Skip k values that can't encode any k-mers from 100bp reads
        if (k >= 100) {
            std::cout << "Skipping k=" << k
                      << " (>= read length 100bp)\n";
            continue;
        }

        std::cout << "Benchmarking k=" << k << "  ["
                  << NUM_RUNS << " runs]";
        std::cout.flush();

        KResult kr;
        kr.k = k;

        for (int run = 0; run < NUM_RUNS; ++run) {
            std::cout << " run" << (run + 1);
            std::cout.flush();

            try {
                StageResult r = runOnce(inputPath, k, totalBases);
                kr.parseMs.push_back(r.parseMs);
                kr.encodeMs.push_back(r.encodeMs);
                kr.graphMs.push_back(r.graphMs);
                kr.contigMs.push_back(r.contigMs);
                kr.scaffoldMs.push_back(r.scaffoldMs);
                kr.totalMs.push_back(r.totalMs);
                kr.peakRamMB.push_back(r.peakRamMB);

                // Assembly quality metrics from the last run
                if (run == NUM_RUNS - 1) {
                    kr.contigCount   = r.contigCount;
                    kr.scaffoldCount = r.scaffoldCount;
                    kr.n50           = r.n50;
                }
            } catch (const std::exception& e) {
                std::cout << "\n  ERROR on k=" << k
                          << " run " << (run + 1)
                          << ": " << e.what() << "\n";
                break;
            }
        }

        std::cout << "  done\n";
        results.push_back(kr);
    }

    // Print results table
    std::cout << "\n";
    std::cout << "Results  (mean ± stddev across " << NUM_RUNS << " runs)\n";
    printHeader();

    for (const auto& r : results)
        printRow(r);

    printSeparator();

    // Best total time
    if (!results.empty()) {
        auto best = std::min_element(results.begin(), results.end(),
            [](const KResult& a, const KResult& b) {
                return mean(a.totalMs) < mean(b.totalMs);
            });
        std::cout << "\nFastest configuration: k=" << best->k
                  << "  total=" << std::fixed << std::setprecision(1)
                  << mean(best->totalMs) << " ms"
                  << "  N50=" << best->n50 << " bp"
                  << "  RAM=" << mean(std::vector<double>(
                        best->peakRamMB.begin(),
                        best->peakRamMB.end()))
                  << " MB\n";

        // Best N50
        auto bestN50 = std::max_element(results.begin(), results.end(),
            [](const KResult& a, const KResult& b) {
                return a.n50 < b.n50;
            });
        std::cout << "Best assembly quality: k=" << bestN50->k
                  << "  N50=" << bestN50->n50 << " bp"
                  << "  contigs=" << bestN50->contigCount << "\n";
    }

    std::cout << "\n";
    return 0;
}